      en:[{text:"What does an LLM fundamentally do?",options:["It searches for the answer in a database","It predicts the most probable text word by word","It reasons like a human expert","It searches the internet in real time"],correct:1},{text:"What is a hallucination in the context of an LLM?",options:["A network connection error","A fixable software bug","A false statement produced with confidence, a structural consequence of the model","An incomplete answer due to a too-short prompt"],correct:2},{text:"Why doesn't an LLM have memory between sessions?",options:["It's a security choice by the developers","Each conversation starts from zero by design","Memory is reserved for paid models","It's a known bug not yet fixed"],correct:1},{text:"What is the right posture toward an agent's output?",options:["Approve it quickly if the formatting looks right","Systematically reject it and redo everything manually","Treat it as a draft to validate, especially on factual points","Submit it to a second agent for validation"],correct:2},{text:"The quality of an LLM's output mainly depends on:",options:["The speed of the internet connection","The version of the model used","The precision and context provided in the prompt","The time of day it's used"],correct:2}]
