      en:[{text:"In which case are hallucinations most frequent?",options:["When asking for a general rephrasing","When asking for creative brainstorming","When asking for precise numerical data or specific references","When asking open-ended questions"],correct:2},{text:"What is confirmation bias in the context of an LLM?",options:["The model always copies the previous answer","The model tends to confirm the conclusion suggested by the prompt's wording","The model refuses negative questions","The model favors short answers"],correct:1},{text:"How can you avoid confirmation bias?",options:["Ask very short questions","Phrase questions neutrally or adversarially","Use a different model","Ask the same question several times"],correct:1},{text:"Why shouldn't you assume Coday remembers a previous session?",options:["It's a paid option","By default, every session starts from zero","Memory is reserved for administrators","It's a known bug"],correct:1},{text:"An LLM doesn't know about recent events because:",options:["The internet is blocked for security reasons","It has a training cutoff date beyond which it has no data","Recent events aren't relevant to work","It's a deliberate choice to avoid misinformation"],correct:1}]
